<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, user-scalable=no, initial-scale=1.0, maximum-scale=1.0, minimum-scale=1.0">
  <title>User Registration Form</title>
  <style>
    .error {
      color: red;
    }
  </style>
  <script>
    function validateForm() {
      var name = document.forms["registration"]["name"].value;
      var email = document.forms["registration"]["email"].value;
      var password = document.forms["registration"]["password"].value;
      var confirmPassword = document.forms["registration"]["confirm_password"].value;
      var errorMessages = [];

      // Get error element
      var errorDiv = document.getElementById('error-messages');
      if(!errorDiv){
        errorDiv = document.createElement('div');
        errorDiv.id = 'error-messages';
        document.querySelector('form').insertBefore(errorDiv, document.querySelector('input[type="submit"]')); // Insert before submit button
      } else {
        errorDiv.innerHTML = ''; // Clear previous errors
      }

      // Name validation
      if (name === "") {
        errorMessages.push("Full Name must be filled out.");
      }

      // Email validation
      if (email === "") {
        errorMessages.push("Email Address must be filled out.");
      } else {
        var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(email)) {
          errorMessages.push("Invalid email format.");
        }
      }

      // Password validation
      if (password === "") {
        errorMessages.push("Password must be filled out.");
      } else if (password.length < 8) {
        errorMessages.push("Password must be at least 8 characters long.");
      }

      // Confirm Password validation
      if (confirmPassword === "") {
        errorMessages.push("Confirm Password must be filled out.");
      } else if (password !== confirmPassword) {
        errorMessages.push("Passwords do not match.");
      }

      // Display error messages
      if (errorMessages.length > 0) {
        errorMessages.forEach(message => {
          var errorElement = document.createElement('p');
          errorElement.className = 'error';
          errorElement.textContent = message;
          errorDiv.appendChild(errorElement);
        });
        return false; // Prevent form submission
      }

      return true; // Allow form submission
    }
  </script>
</head>
