```python
from typing import List, Tuple

def is_strongly_connected(edges: List[Tuple[int, int]]) -> bool:
    """
    Determines if a directed graph is strongly connected.

    Args:
        edges: A list of tuples representing the edges of the directed graph.

    Returns:
        True if the graph is strongly connected, otherwise False.
    """

    if not edges:
        return True

    graph = {}
    vertices = set()
    for u, v in edges:
        graph.setdefault(u, []).append(v)
        vertices.add(u)
        vertices.add(v)

    if not vertices:
        return True

    start_node = next(iter(vertices))

    def dfs(node, visited, graph):
        visited.add(node)
        if node in graph:
            for neighbor in graph[node]:
                if neighbor not in visited:
                    dfs(neighbor, visited, graph)

    visited = set()
    dfs(start_node, visited, graph)

    if len(visited) != len(vertices):
        return False

    reversed_graph = {}
    for u, v in edges:
        reversed_graph.setdefault(v, []).append(u)

    visited = set()
    dfs(start_node, visited, reversed_graph)

    return len(visited) == len(vertices)
```

A directed graph is strongly connected if every vertex is reachable from every other vertex. The code first constructs the graph and its reverse. Then, it performs Depth-First Search (DFS) from an arbitrary starting node on both the original and reversed graphs, checking if all vertices are visited in each case. If so, the graph is strongly connected.

