import ast
import operator

def calculate(expression):
    """Safely evaluates a mathematical expression using AST."""
    node = ast.parse(expression, mode='eval').body
    return _evaluate(node)

def _evaluate(node):
    """Recursive helper function to evaluate AST nodes."""
    if isinstance(node, ast.Num):
        return node.n
    elif isinstance(node, ast.BinOp):
        op = {
            ast.Add: operator.add,
            ast.Sub: operator.sub,
            ast.Mult: operator.mul,
            ast.Div: operator.truediv
        }[type(node.op)]
        return op(_evaluate(node.left), _evaluate(node.right))
    elif isinstance(node, ast.UnaryOp):
        if isinstance(node.op, ast.USub):
            return -_evaluate(node.operand)
        else:
            raise ValueError("Unsupported unary operator")
    elif isinstance(node, ast.Name):
        raise ValueError("Variables are not supported")
    else:
        raise ValueError("Unsupported node type")

if __name__ == "__main__":
    expression = input()
    result = calculate(expression)
    print(result)
```

The code parses the input expression into an Abstract Syntax Tree (AST) using `ast.parse()`.  The `calculate()` function then recursively traverses the AST using `_evaluate()`. It handles numbers (`ast.Num`), binary operations (`ast.BinOp`) with supported operators (addition, subtraction, multiplication, division), and unary minus (`ast.UnaryOp`). It raises errors for unsupported nodes or variables, ensuring safety.

