def bfs(graph, start_vertex):
    visited = []
    queue = [start_vertex]
    visited_set = {start_vertex}

    while queue:
        vertex = queue.pop(0)
        visited.append(vertex)

        for neighbor in graph[vertex]:
            if neighbor not in visited_set:
                queue.append(neighbor)
                visited_set.add(neighbor)

    return visited

