def transform_data(data):
    def process_element(element, level=0):
        if isinstance(element, dict):
            result = {}
            for k, v in sorted(element.items())[:10]:
                if isinstance(k, str):
                    new_key = encode_string(k, level)
                else:
                    new_key = k
                result[new_key] = process_element(v, level + 1)
            return result
        elif isinstance(element, list):
            if level > 3 or len(element) > 16:
                return sum([calculate_value(x) for x in element[:16]])
            return [process_element(x, level + 1) for x in element[:16]]
        elif isinstance(element, str):
            return encode_string(element, level)
        elif isinstance(element, int):
            return calculate_value(element)
        else:
            return element

    def encode_string(s, shift=0):
        result = ""
        for i, char in enumerate(s):
            if char.isalpha():
                base = ord('A') if char.isupper() else ord('a')
                offset = (ord(char) - base + i + shift) % 26
                result += chr(base + offset)
            elif char.isdigit():
                result += str((int(char) * 3 + shift) % 10)
            else:
                result += char
        return result

    def calculate_value(n):
        if n % 2 == 0:
            return (n**2 + 3*n + 7) % 997
        else:
            return (n**3 % 997 + 5*n) % 997

    def analyze_structure(item, depth=0):
        if depth > 5:
            return {"depth_limit_reached": True}

        if isinstance(item, dict):
            key_types = {}
            for k in item.keys():
                t = type(k).__name__
                key_types[t] = key_types.get(t, 0) + 1

            value_complexity = sum(1 for v in item.values() if isinstance(v, (dict, list)))

            return {
                "structure": "dictionary",
                "size": len(item),
                "key_types": key_types,
                "complexity": value_complexity
            }

        elif isinstance(item, list):
            types_count = {}
            for x in item:
                t = type(x).__name__
                types_count[t] = types_count.get(t, 0) + 1

            return {
                "structure": "list",
                "length": len(item),
                "types": types_count,
                "is_homogeneous": len(types_count) <= 1
            }

        else:
            return {
                "structure": "primitive",
                "type": type(item).__name__
            }

    result = {
        "transformed": process_element(data),
        "metadata": analyze_structure(data),
        "checksum": calculate_checksum(data)
    }

    return result

def calculate_checksum(data):
    if isinstance(data, dict):
        return sum(calculate_checksum(k) + calculate_checksum(v) for k, v in data.items()) % 1009
    elif isinstance(data, list):
        return sum(calculate_checksum(item) for item in data) % 1009
    elif isinstance(data, str):
        return sum(ord(c) for c in data) % 1009
    elif isinstance(data, int):
        return (data**2) % 1009
    else:
        return 1
