import numpy as np

def matrix_transformation_system(input_data):
    if not isinstance(input_data, dict):
        input_data = {"value": input_data}

    sequence = []
    if "sequence" in input_data and isinstance(input_data["sequence"], list):
        for item in input_data["sequence"][:16]:
            if isinstance(item, (int, float)) and item == int(item):
                sequence.append(int(item) % 100)
            elif isinstance(item, str) and item:
                sequence.append(ord(item[0]) % 100)

    if not sequence and "value" in input_data:
        val = input_data["value"]
        if isinstance(val, int):
            sequence = [int(d) for d in str(abs(val))[:16]]
            if not sequence:
                sequence = [0]
        elif isinstance(val, str):
            sequence = [ord(c) % 100 for c in val[:16]]

    if not sequence:
        sequence = [1, 2, 3, 4]

    size = 2
    if len(sequence) > 4:
        size = 3
    if len(sequence) > 9:
        size = 4

    target_length = size * size
    sequence = sequence[:target_length]
    while len(sequence) < target_length:
        next_val = (sequence[-1] + sequence[0]) % 100
        sequence.append(next_val)

    matrix = np.array(sequence).reshape(size, size)

    transform = np.zeros((size, size), dtype=int)
    for i in range(size):
        for j in range(size):
            transform[i, j] = ((i + 1) * (j + 1)) % 10

    encoded = np.zeros((size, size), dtype=int)
    for i in range(size):
        for j in range(size):
            if transform[i, j] % 2 == 0:
                encoded[i, j] = (matrix[i, j] + transform[i, j]) % 100
            else:
                encoded[i, j] = (matrix[i, j] * transform[i, j]) % 100

    row_sums = [int(sum(row)) for row in encoded]
    col_sums = [int(sum(encoded[:, j])) for j in range(size)]
    diag_sum = int(sum(np.diag(encoded)))
    anti_diag_sum = int(sum(np.diag(np.fliplr(encoded))))

    code = (sum(row_sums) * diag_sum + anti_diag_sum) % 1000

    result = {
        "original": matrix.tolist(),
        "transform": transform.tolist(),
        "encoded": encoded.tolist(),
        "features": {
            "row_sums": row_sums,
            "col_sums": col_sums,
            "diag_sum": diag_sum,
            "anti_diag_sum": anti_diag_sum
        },
        "code": code
    }

    return result
