```python
from more_itertools import windowed, circular_shifts, pairwise

def energy_load_balancer(data):
    if isinstance(data, dict):
        return balance_grid_config(data)
    elif isinstance(data, list):
        return balance_load_series(data)
    else:
        base = data if isinstance(data, int) else len(str(data))
        return {"capacity": base * 3, "threshold": base * 2}

def balance_grid_config(config):
    base_capacity = config.get("base_capacity", 100)
    peak_threshold = config.get("peak_threshold", 150)
    load_series = config.get("load_series", [base_capacity])
    priority_sectors = config.get("priority_sectors", ["residential", "medical", "industrial"])

    balanced_loads, excess = balance_loads(load_series, peak_threshold)

    # Allocate to sectors based on priority
    sector_allocations = {}
    total_load = sum(balanced_loads)
    remaining_sectors = len(priority_sectors)

    for sector in priority_sectors:
        allocation = total_load // remaining_sectors
        sector_allocations[sector] = allocation
        total_load -= allocation
        remaining_sectors -= 1

    # Find peak periods using windowed
    peak_periods = []
    for i, window in enumerate(windowed(balanced_loads, 3, fillvalue=base_capacity)):
        if sum(window) // 3 > peak_threshold // 2:
            peak_periods.append(i)
            if len(peak_periods) >= 5:
                break

    # Generate shift patterns using circular_shifts
    shift_patterns = []
    for i, shift in enumerate(circular_shifts(range(min(5, len(balanced_loads))))):
        shift_patterns.append(list(shift))
        if i >= 2:
            break

    return {
        "balanced_loads": balanced_loads,
        "allocations": sector_allocations,
        "peak_periods": peak_periods,
        "shifts": shift_patterns,
        "excess": excess
    }

def balance_load_series(loads):
    if not loads:
        return {"balanced": [], "status": "empty"}

    base_capacity = sum(loads) // max(1, len(loads))
    peak_threshold = base_capacity + (max(loads) - min(loads)) // 2

    balanced_loads, excess = balance_loads(loads, peak_threshold)

    # Calculate grid stability using pairwise
    pairs = list(pairwise(balanced_loads + [balanced_loads[0]] if balanced_loads else []))
    stability_score = 100 - sum(abs(b - a) for a, b in pairs) // max(1, len(pairs))

    return {
        "balanced": balanced_loads,
        "base": base_capacity,
        "threshold": peak_threshold,
        "stability": stability_score,
        "excess": excess
    }

def balance_loads(loads, threshold):
    balanced = []
    excess = 0

    for i, load in enumerate(loads):
        next_load = loads[(i + 1) % len(loads)] if loads else load
        future_peak = next_load > threshold

        if load > threshold:
            excess += (load - threshold)
            balanced.append(threshold)
        else:
            deficit = threshold - load
            if future_peak and excess < deficit:
                balanced.append(load)
            elif excess >= deficit:
                balanced.append(load + deficit)
                excess -= deficit
            else:
                balanced.append(load + excess)
                excess = 0

    return balanced, excess
