        int[][] test2 = {{1}, {2}, {3}};
        int[] result2 = solution.convertTo1D(test2);
        System.out.println("Test 2: " + Arrays.toString(result2)); // Expected: [1, 2, 3]

        int[][] test3 = {{1, 2}, {3, 4}};
        int[] result3 = solution.convertTo1D(test3);
        System.out.println("Test 3: " + Arrays.toString(result3)); // Expected: [1, 2, 3, 4]

        int[][] test4 = {{5, 10, 15}};
        int[] result4 = solution.convertTo1D(test4);
        System.out.println("Test 4: " + Arrays.toString(result4)); // Expected: [5, 10, 15]
    }
}
