void segregateEvenOdd(int arr[], int n) {
    std::vector<int> even, odd;
    for (int i = 0; i < n; ++i) {
        if (arr[i] % 2 == 0) {
            even.push_back(arr[i]);
        } else {
            odd.push_back(arr[i]);
        }
    }
    std::sort(even.begin(), even.end());
    std::sort(odd.begin(), odd.end());
    int index = 0;
    for (int i = 0; i < even.size(); ++i) {
        arr[index++] = even[i];
    }
    for (int i = 0; i < odd.size(); ++i) {
        arr[index++] = odd[i];
    }
}
```

The solution segregates even and odd numbers into separate vectors, sorts each vector, and then merges them back into the original array in the desired order.  This achieves O(N log N) time complexity due to sorting and O(N) auxiliary space for the vectors.

