def sieve_of_eratosthenes(limit):
    """
    Finds all prime numbers up to a given limit using the Sieve of Eratosthenes.
    """
    primes = [True] * (limit + 1)
    primes[0] = primes[1] = False
    for i in range(2, int(limit**0.5) + 1):
        if primes[i]:
            for j in range(i*i, limit + 1, i):
                primes[j] = False
    return [i for i, is_prime in enumerate(primes) if is_prime]


def find_primes_in_ranges(n):
    """
    Reads ranges and prints prime numbers within each range.
    """
    for _ in range(n):
        start, end = map(int, input().split())
        primes = sieve_of_eratosthenes(end)
        range_primes = [p for p in primes if start <= p <= end]
        if range_primes:
            print(*range_primes)
        else:
            print()

if __name__ == "__main__":
    n = int(input())
    find_primes_in_ranges(n)
