def convert_version(ver_str: str) -> str:
    """Converts a git version string to a PEP440 compatible format."""
    if '-' not in ver_str:
        return ver_str

    if ver_str.count('-') == 1:
        return ver_str.split('-')[0] + '+dirty'

    if ver_str.count('-') == 2:
        parts = ver_str.split('-')
        return f'{parts[0]}.post0.dev{parts[1]}+{parts[2]}'

    if ver_str.count('-') == 3:
        parts = ver_str.split('-')
        return f'{parts[0]}.post0.dev{parts[1]}+{parts[2]}.dirty'

    raise RuntimeError('Invalid version string')
```

