def majority_element(nums):
    """Finds the majority element in a list of integers."""
    if not nums:
        return None
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1
    for num, count in counts.items():
        if count > len(nums) // 2:
            return num
    return None

