def solve():
    n = int(input())
    a = list(map(int, input().split()))

    for i in range(1, 1 << n):
        subset = []
        for j in range(n):
            if (i >> j) & 1:
                subset.append(a[j])

        if len(set(subset)) != len(subset):
            continue

        if len(subset) > 0:
            gcd_val = subset[0]
            for k in range(1, len(subset)):
                gcd_val = gcd(gcd_val, subset[k])

            if gcd_val == 1:
                print("YES")
                return

    print("NO")

def gcd(a, b):
