def convert_number(number, conversion_type):
    """Converts a number between different formats."""
    if conversion_type == 'int_to_roman':
        return int_to_roman(number)
    elif conversion_type == 'roman_to_int':
        return roman_to_int(number)
    elif conversion_type == 'int_to_hex':
        return int_to_hex(number)
    elif conversion_type == 'hex_to_int':
        return hex_to_int(number)
    else:
        raise ValueError("Invalid conversion type.")

def int_to_roman(num):
    roman_map = { 1: 'I', 4: 'IV', 5: 'V', 9: 'IX', 10: 'X', 40: 'XL', 50: 'L', 90: 'XC', 100: 'C', 400: 'CD', 500: 'D', 900: 'CM', 1000: 'M'}
    i = 12
    result = ""
    while num != 0:
        if list(roman_map.keys())[i] <= num:
            result += list(roman_map.values())[i]
            num -= list(roman_map.keys())[i]
        else:
            i -= 1
    return result

def roman_to_int(roman):
    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    result = 0
    prev_value = 0
    for i in range(len(roman) - 1, -1, -1):
        curr_value = roman_map[roman[i]]
        if curr_value < prev_value:
            result -= curr_value
        else:
            result += curr_value
        prev_value = curr_value
    return result

def int_to_hex(num):
    return hex(num)[2:].upper()

def hex_to_int(hex_str):
    return int(hex_str, 16)
```

The `convert_number` function acts as a dispatcher. It takes a number and a `conversion_type` string. Based on the `conversion_type`, it calls the appropriate helper function (`int_to_roman`, `roman_to_int`, `int_to_hex`, or `hex_to_int`). An invalid `conversion_type` raises a `ValueError`. Each helper function performs its specific conversion, returning the result in the correct format (string or integer).

