import ast

def sum_numeric_values(input_string):
    """
    Calculates the sum of all numbers in a Python literal structure.
    """
    try:
        data = ast.literal_eval(input_string)
        total_sum = 0

        def traverse(obj):
            nonlocal total_sum
            if isinstance(obj, (int, float)):
                total_sum += obj
            elif isinstance(obj, list):
                for item in obj:
                    traverse(item)
            elif isinstance(obj, dict):
                for value in obj.values():
                    traverse(value)

        traverse(data)
        return total_sum
    except (SyntaxError, ValueError):
        return 0  # Handle invalid input

