        return N

    count = 0
    for i in range(1, int(N**0.5) + 1):
        if i * i <= N:
            is_divisible = False
            for j in [2, 3, 4, 5, 6, 7, 8, 9, 10]:
                if i % j == 0:
                    is_divisible = True
                    break
            if not is_divisible:
