def flatten_dict(d):
    """Flattens a nested dictionary into a single dictionary with dot-separated keys."""
    items = []
    for k, v in d.items():
        if isinstance(v, dict):
            new_items = flatten_dict(v).items()
            for nk, nv in new_items:
