    int n;
    cin >> n;

    int t[n + 1];
    t[0] = 0;
    t[1] = 0;
    t[2] = 1;

    for (int i = 3; i <= n; ++i) {
        t[i] = (t[i - 1] + t[i - 2] + t[i - 3]) % 26;
    }

    cout << t[n] << endl;

    return 0;
