def discounted_prices(prices, discount_percentage, depth=0):
    if depth > 1000:
        return None  # Prevent stack overflow

    if not prices:
        return []

    price = prices[0]
    discounted_price = price * (1 - discount_percentage / 100)
    result = [round(discounted_price, 2)]

    if len(prices) > 1:
        remaining_prices = prices[1:]
        remaining_result = discounted_prices(remaining_prices, discount_percentage, depth + 1)
        if remaining_result is not None:
            result.extend(remaining_result)
        else:
            return None # Propagate stack overflow

    return result


if __name__ == "__main__":
    n = int(input())
    prices = list(map(float, input().split()))
    discount_percentage = float(input())

    discounted_prices_list = discounted_prices(prices, discount_percentage)

    if discounted_prices_list:
        print(*discounted_prices_list)
    else:
        print("Recursion depth exceeded.")
```

The code recursively calculates discounted prices. The `discounted_prices` function takes a list of prices, discount percentage, and recursion depth as input. It calculates the discounted price for the first element and recursively calls itself for the remaining prices, incrementing the depth. A depth check prevents stack overflow. The results are combined, and rounded to two decimal places.

