import re

def validate_registration(username: str, password: str, password_confirmation: str) -> bool:
    """Validates user registration information."""

    # Validate username
    if not re.match("^[a-zA-Z0-9 ]+$", username):
        return False

    # Validate password
    if len(password) < 8:
        return False
    if not re.search("[a-z]", password):
        return False
    if not re.search("[A-Z]", password):
        return False
    if not re.search("[0-9]", password):
        return False
    if not re.search("[!@#$%^&*()]", password):
        return False

    # Validate password confirmation
    if password != password_confirmation:
        return False

    return True
