import json
from datetime import datetime

posts = []
next_id = 1

def create_post(title, content, author):
    global next_id
    date = datetime.utcnow().isoformat()
    post = {"id": next_id, "title": title, "content": content, "author": author, "date": date}
    posts.append(post)
    next_id += 1
    return post

def read_post(id):
    for post in posts:
        if post["id"] == id:
            return post
    return {}

def read_all_posts():
    return posts

def update_post(id, title, content, author):
    for post in posts:
        if post["id"] == id:
            post["title"] = title
            post["content"] = content
            post["author"] = author
            date = datetime.utcnow().isoformat()
            post["date"] = date
            return post
    return {}

def delete_post(id):
    global posts
    posts = [post for post in posts if post["id"] != id]
    return {}

n = int(input())
